// ── Data row type ─────────────────────────────────────────────────────────────

interface Row {
  title: string;
  items: MediaItem[];
  loading: boolean;
}

// ── App ───────────────────────────────────────────────────────────────────────

interface AppProps {
  topBarRight?: React.ReactNode;
  apiKey?: string;
}

export default function App({ topBarRight, apiKey: runtimeApiKey }: AppProps) {
  const [apiKey, setApiKey] = useState<string | null>(() => loadApiKey(runtimeApiKey));
  const [activeNavId, setActiveNavId] = useState('cat:all');

  // Search
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<MediaItem[]>([]);
  const [searchLoading, setSearchLoading] = useState(false);
  const searchTimer = useRef<ReturnType<typeof setTimeout>>();

  // Content rows
  const [rows, setRows] = useState<Row[]>([]);

  // Detail modal
  const [selected, setSelected] = useState<MediaItem | null>(null);

  // Library version counter — bumped when user changes favorites/seen
  const [libraryVersion, setLibraryVersion] = useState(0);
  const onLibraryChange = useCallback(() => setLibraryVersion((v) => v + 1), []);

  useEffect(() => {
    setApiKey(loadApiKey(runtimeApiKey));
  }, [runtimeApiKey]);

  // ── API key save ─────────────────────────────────────────────────────────────

  const handleApiKeySave = (key: string) => {
    saveApiKey(key);
    setApiKey(key);
  };

  // ── Load content rows ────────────────────────────────────────────────────────

  const loadRows = useCallback(async (key: string, navId: string) => {
    // Library views — read from localStorage, no API call
    if (navId === 'lib:favorites') {
      const items = loadFavorites();
      setRows([{ title: 'My Favorites', items, loading: false }]);
      return;
    }
    if (navId === 'lib:seen') {
      const items = loadSeen();
      setRows([{ title: 'Recently Seen (last 15)', items, loading: false }]);
      return;
    }

    // Streaming service filter
    if (navId.startsWith('stream:')) {
      const providerId = parseInt(navId.slice(7), 10);
      const provider = STREAMING_PROVIDERS.find((p) => p.id === providerId);
      const name = provider?.name ?? 'Streaming';
      setRows([
        { title: `${name} — Movies`, items: [], loading: true },
        { title: `${name} — TV Shows`, items: [], loading: true },
      ]);
      const [movies, tv] = await Promise.all([
        getByStreamingProvider(key, providerId, 'movie'),
        getByStreamingProvider(key, providerId, 'tv'),
      ]);
      setRows([
        { title: `${name} — Movies`, items: movies, loading: false },
        { title: `${name} — TV Shows`, items: tv, loading: false },
      ]);
      return;
    }

    // Year filter
    if (navId.startsWith('year:')) {
      const year = parseInt(navId.slice(5), 10);
      setRows([
        { title: `Movies — ${year}`, items: [], loading: true },
        { title: `TV Shows — ${year}`, items: [], loading: true },
      ]);
      const [movies, tv] = await Promise.all([
        getByYear(key, year, 'movie'),
        getByYear(key, year, 'tv'),
      ]);
      setRows([
        { title: `Movies — ${year}`, items: movies, loading: false },
        { title: `TV Shows — ${year}`, items: tv, loading: false },
      ]);
      return;
    }

    // Genre filter
    if (navId.startsWith('genre:')) {
      const genreId = parseInt(navId.slice(6), 10);
      const genreName = GENRE_MAP[genreId] ?? 'Genre';
      setRows([
        { title: `${genreName} — Movies`, items: [], loading: true },
        { title: `${genreName} — TV Shows`, items: [], loading: true },
      ]);
      const [movies, tv] = await Promise.all([
        getByGenre(key, genreId, 'movie'),
        getByGenre(key, genreId, 'tv'),
      ]);
      setRows([
        { title: `${genreName} — Movies`, items: movies, loading: false },
        { title: `${genreName} — TV Shows`, items: tv, loading: false },
      ]);
      return;
    }

    if (navId === 'cat:documentaries') {
      setRows([{ title: 'Documentaries', items: [], loading: true }]);
      const docs = await getDocumentaries(key);
      setRows([{ title: 'Documentaries', items: docs, loading: false }]);
      return;
    }

    if (navId === 'cat:movies') {
      setRows([
        { title: 'Popular Movies', items: [], loading: true },
        { title: 'Top Rated Movies', items: [], loading: true },
      ]);
      const [popular, topRated] = await Promise.all([
        getPopularMovies(key),
        getTopRated(key, 'movie'),
      ]);
      setRows([
        { title: 'Popular Movies', items: popular, loading: false },
        { title: 'Top Rated Movies', items: topRated, loading: false },
      ]);
      return;
    }

    if (navId === 'cat:tv') {
      setRows([
        { title: 'Popular TV Shows', items: [], loading: true },
        { title: 'Top Rated TV Shows', items: [], loading: true },
      ]);
      const [popular, topRated] = await Promise.all([
        getPopularTv(key),
        getTopRated(key, 'tv'),
      ]);
      setRows([
        { title: 'Popular TV Shows', items: popular, loading: false },
        { title: 'Top Rated TV Shows', items: topRated, loading: false },
      ]);
      return;
    }

    // cat:all — Discover home
    setRows([
      { title: 'Trending This Week', items: [], loading: true },
      { title: 'Popular Movies', items: [], loading: true },
      { title: 'Popular TV Shows', items: [], loading: true },
      { title: 'Top Rated Movies', items: [], loading: true },
      { title: 'Documentaries', items: [], loading: true },
    ]);

    const [trending, movies, tv, topMovies, docs] = await Promise.all([
      getTrending(key),
      getPopularMovies(key),
      getPopularTv(key),
      getTopRated(key, 'movie'),
      getDocumentaries(key),
    ]);

    setRows([
      { title: 'Trending This Week', items: trending, loading: false },
      { title: 'Popular Movies', items: movies, loading: false },
      { title: 'Popular TV Shows', items: tv, loading: false },
      { title: 'Top Rated Movies', items: topMovies, loading: false },
      { title: 'Documentaries', items: docs, loading: false },
    ]);
  }, []);

  // Re-load when nav changes or library is updated (for lib: views)
  useEffect(() => {
    if (!apiKey) return;
    loadRows(apiKey, activeNavId);
  }, [apiKey, activeNavId, loadRows, libraryVersion]);

  // ── Search ───────────────────────────────────────────────────────────────────

  useEffect(() => {
    if (!apiKey) return;
    clearTimeout(searchTimer.current);
    if (!searchQuery.trim()) {
      setSearchResults([]);
      return;
    }
    setSearchLoading(true);
    searchTimer.current = setTimeout(async () => {
      try {
        const results = await search(apiKey, searchQuery.trim());
        setSearchResults(results);
      } catch {
        setSearchResults([]);
      } finally {
        setSearchLoading(false);
      }
    }, 400);
  }, [apiKey, searchQuery]);

  // ── Nav select ───────────────────────────────────────────────────────────────

  const handleNavSelect = useCallback((entry: NavEntry) => {
    if (entry.id.startsWith('group:')) return;
    setActiveNavId(entry.id);
    setSearchQuery('');
  }, []);

  // ── Hero item ────────────────────────────────────────────────────────────────

  const heroItem = rows[0]?.items?.find((i) => i.backdrop_path) ?? null;
  const isSearching = searchQuery.trim().length > 0;

  function getPageTitle(navId: string): string {
    if (navId.startsWith('year:')) return navId.slice(5);
    if (navId.startsWith('genre:')) return GENRE_MAP[parseInt(navId.slice(6), 10)] ?? 'Genre';
    if (navId.startsWith('stream:')) {
      const p = STREAMING_PROVIDERS.find((p) => p.id === parseInt(navId.slice(7), 10));
      return p?.name ?? 'Streaming';
    }
    const labels: Record<string, string> = {
      'cat:all': 'Discover',
      'cat:movies': 'Movies',
      'cat:tv': 'TV Shows',
      'cat:documentaries': 'Documentaries',
      'lib:favorites': 'My Favorites',
      'lib:seen': 'Recently Seen',
    };
    return labels[navId] ?? '';
  }

  // ── Render ───────────────────────────────────────────────────────────────────

  if (!apiKey) {
    return <ApiKeySetup onSave={handleApiKeySave} />;
  }

  const searchBar = (
    <SearchBar>
      <Search size={15} color={theme.colors.mainTextMuted} />
      <SearchInput
        placeholder="Search movies, shows…"
        value={searchQuery}
        onChange={(e) => setSearchQuery(e.target.value)}
      />
      {searchQuery && (
        <ClearBtn onClick={() => setSearchQuery('')} aria-label="Clear search">
          <X size={14} />
        </ClearBtn>
      )}
    </SearchBar>
  );

  const sidebar = (
    <NavTree
      entries={NAV_ENTRIES}
      activeId={activeNavId}
      onSelect={handleNavSelect}
    />
  );

  const isLibraryEmpty =
    (activeNavId === 'lib:favorites' || activeNavId === 'lib:seen') &&
    !rows[0]?.loading &&
    rows[0]?.items.length === 0;

  return (
    <>
      <Layout
        title="Movies & Series"
        sidebar={sidebar}
        activeId={activeNavId}
        topBarRight={
          <>
            {searchBar}
            {topBarRight}
          </>
        }
      >
        <MainScroll>
          {isSearching ? (
            <>
              <FilterHeader>
                <FilterTitle>
                  {searchLoading
                    ? 'Searching…'
                    : searchResults.length > 0
                    ? `Results for "${searchQuery}"`
                    : `No results for "${searchQuery}"`}
                </FilterTitle>
              </FilterHeader>
              {!searchLoading && searchResults.length === 0 ? (
                <EmptyState>
                  <span style={{ fontSize: 40 }}>🔍</span>
                  Nothing found — try a different title
                </EmptyState>
              ) : (
                <ContentRow
                  title=""
                  items={searchResults}
                  loading={searchLoading}
                  onSelect={setSelected}
                />
              )}
            </>
          ) : (
            <>
              {/* Hero — only on home/discover view */}
              {activeNavId === 'cat:all' && heroItem && (
                <Hero item={heroItem} onPlay={setSelected} onMore={setSelected} />
              )}

              {/* Page header for filtered views */}
              {activeNavId !== 'cat:all' && (
                <FilterHeader>
                  <FilterTitle>{getPageTitle(activeNavId)}</FilterTitle>
                </FilterHeader>
              )}

              {isLibraryEmpty ? (
                <EmptyState>
                  <span style={{ fontSize: 40 }}>
                    {activeNavId === 'lib:favorites' ? '❤️' : '👁️'}
                  </span>
                  {activeNavId === 'lib:favorites'
                    ? 'No favorites yet — open any title and hit ❤️'
                    : 'No seen titles yet — open any title and mark it as seen'}
                </EmptyState>
              ) : (
                rows.map((row) => (
                  <ContentRow
                    key={row.title}
                    title={row.title}
                    items={row.items}
                    loading={row.loading}
                    onSelect={setSelected}
                  />
                ))
              )}
            </>
          )}
        </MainScroll>
      </Layout>

      {selected && (
        <DetailModal
          item={selected}
          apiKey={apiKey}
          onClose={() => setSelected(null)}
          onLibraryChange={onLibraryChange}
        />
      )}
    </>
  );
}
